package ru.mareanexx.reader_impl.data.mock

import java.io.ByteArrayOutputStream
import java.util.zip.CRC32
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/** Авторский демонстрационный текст: не содержимое книги с обложки каталога. */
internal object DemoEpub {
    private val cache = mutableMapOf<String, ByteArray>()
    @Synchronized fun bytes(id: String, title: String): ByteArray = cache.getOrPut(id) {
        val output = ByteArrayOutputStream()
        ZipOutputStream(output).use { zip ->
            fun entry(path: String, text: String, stored: Boolean = false) {
                val bytes = text.toByteArray()
                val item = ZipEntry(path).apply {
                    time = 0L
                    if (stored) { method = ZipEntry.STORED; size = bytes.size.toLong(); compressedSize = size; crc = CRC32().apply { update(bytes) }.value }
                }
                zip.putNextEntry(item); zip.write(bytes); zip.closeEntry()
            }
            entry("mimetype", "application/epub+zip", true)
            entry("META-INF/container.xml", """<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container" version="1.0"><rootfiles><rootfile full-path="EPUB/package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>""")
            entry("EPUB/package.opf", """<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="uid"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:identifier id="uid">elementa:$id</dc:identifier><dc:title>${escape(title)}</dc:title><dc:language>ru</dc:language><meta property="dcterms:modified">2026-10-18T00:00:00Z</meta></metadata><manifest><item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>${(1..4).joinToString("") { "<item id=\"c$it\" href=\"chapter$it.xhtml\" media-type=\"application/xhtml+xml\" properties=\"mathml\"/>" }}</manifest><spine>${(1..4).joinToString("") { "<itemref idref=\"c$it\"/>" }}</spine></package>""")
            entry("EPUB/nav.xhtml", """<html xmlns="http://www.w3.org/1999/xhtml"><head><title>Оглавление</title></head><body><nav xmlns:epub="http://www.idpf.org/2007/ops" epub:type="toc"><ol>${headings.mapIndexed { i, h -> "<li><a href=\"chapter${i+1}.xhtml\">$h</a></li>" }.joinToString("")}</ol></nav></body></html>""")
            headings.forEachIndexed { index, heading ->
                entry("EPUB/chapter${index+1}.xhtml", """<html xmlns="http://www.w3.org/1999/xhtml"><head><title>$heading</title></head><body><h1>$heading</h1>${if (index == 0) "<p><em>Демонстрационный материал Elementa. Текст создан для проверки ридера и не воспроизводит издание с обложки.</em></p>" else ""}${sections[index].joinToString("")}${examples(index)}</body></html>""")
            }
        }
        output.toByteArray()
    }
    private fun escape(value: String) = value.replace("&", "&amp;").replace("<", "&lt;")
    private val headings = listOf("Язык химии: от атома к веществу", "Связи и строение молекул", "Реакции и равновесие", "Как читать химическую литературу")
    private val sections = listOf(
        listOf(
            "<p>Химия изучает состав, строение и превращения веществ. Начать знакомство удобно с простого наблюдения: лёд тает, железо ржавеет, а соль растворяется в воде. За похожими внешними изменениями могут стоять разные процессы. Чтобы отличить их, химик описывает систему на нескольких уровнях — от наблюдаемого опыта до модели частиц.</p>",
            "<p><strong>Атом</strong> — электрически нейтральная частица, состоящая из ядра и электронов. Заряд ядра определяет химический элемент. Массовое число связано с суммой протонов и нейтронов, однако при расчётах обычно используют относительную атомную массу: она учитывает распространённость изотопов.</p>",
            "<p>Молекула воды содержит два атома водорода и один атом кислорода. Запись H<sub>2</sub>O передаёт состав, но сама по себе не показывает пространственное строение. Нижний индекс относится к символу элемента перед ним. Коэффициент перед формулой, напротив, относится ко всей частице.</p>",
            "<h2>Количество вещества</h2><p>Количество вещества связывает мир отдельных частиц с измеряемой массой образца. Его единица — моль. При решении задачи сначала определяют, какие частицы считают: атомы, молекулы, ионы или формульные единицы. Затем выбирают молярную массу именно этих частиц.</p>",
            "<p>Если масса воды равна 18 г, а молярная масса приблизительно 18 г/моль, количество вещества составляет около одного моля. Результат имеет смысл только вместе с единицами. Проверка размерностей помогает заметить ошибку раньше, чем появляется неверный численный ответ.</p>",
            "<blockquote>Полезный приём: перед вычислением проговорить словами, какую величину ищем и что означает каждый символ.</blockquote>",
        ),
        listOf(
            "<p>Свойства вещества зависят не только от набора атомов, но и от того, как они связаны. Одни и те же элементы могут образовать вещества с разными свойствами. Поэтому химическая формула — начало описания, а не его завершение.</p>",
            "<p>В ковалентной связи электронная плотность распределяется между ядрами. При различной электроотрицательности атомов распределение становится несимметричным. Такая связь называется полярной. Однако полярность всей молекулы зависит также от её геометрии.</p>",
            "<p>Для молекулы воды важна угловая форма. Векторы дипольных моментов связей не компенсируют друг друга. У линейной молекулы CO<sub>2</sub> симметрия приводит к компенсации, хотя каждая связь углерод–кислород полярна.</p>",
            "<h2>Ионная модель</h2><p>Ионную связь удобно рассматривать как электростатическое взаимодействие частиц противоположного заряда. В кристалле поваренной соли нет отдельных молекул NaCl: формула показывает соотношение ионов в решётке. Это различие важно при объяснении температуры плавления и электропроводности.</p>",
            "<p>Модели имеют границы применимости. Деление связей на типы упрощает рассуждение, но реальная электронная структура может иметь промежуточный характер. При чтении учебника обращайте внимание, какие допущения использует автор.</p>",
            "<p>Сравнивайте структуру и свойства в одной цепочке: строение частицы, взаимодействия между частицами, наблюдаемое поведение вещества. Такой подход помогает переносить знания на новые примеры, а не запоминать отдельные факты.</p>",
        ),
        listOf(
            "<p>В химической реакции атомы перегруппировываются, образуя новые вещества. Уравнение должно сохранять число атомов каждого элемента и суммарный заряд. Коэффициенты подбирают по этим ограничениям; менять индексы в формулах веществ при уравнивании нельзя.</p>",
            "<p>Например, водород реагирует с кислородом с образованием воды. Коэффициенты показывают отношение количеств вещества участников. Они не означают, что реакция обязательно протекает за один элементарный шаг.</p>",
            "<h2>Скорость и условия</h2><p>Скорость реакции зависит от природы веществ, температуры, концентраций и других условий. Катализатор меняет путь превращения и помогает преодолеть кинетические ограничения. При этом он не изменяет положение термодинамического равновесия.</p>",
            "<p>Динамическое равновесие означает равенство скоростей прямого и обратного процессов. Концентрации участников остаются постоянными, но микроскопические превращения продолжаются. Слово «динамическое» подчёркивает это отличие от полного прекращения реакции.</p>",
            "<p>Константа равновесия относится к заданной температуре. В строгой записи используют активности; в учебных приближениях их иногда заменяют концентрациями. Прежде чем подставлять числа, уточните, в каких условиях допустимо такое приближение.</p>",
            "<p>Если задача содержит несколько стадий, запишите отдельное уравнение для каждой. Затем проверьте общий материальный баланс. Даже аккуратный расчёт не исправит неверную химическую модель процесса.</p>",
        ),
        listOf(
            "<p>Работа с научным текстом отличается от быстрого просмотра. Сначала определите вопрос, на который хотите ответить. Просмотрите заголовки, рисунки и выводы. Это создаёт маршрут чтения и помогает отделить главное от уточняющих деталей.</p>",
            "<p>Встречая незнакомый термин, сохраните короткую заметку со своим объяснением. Цитата полезна как опора, но собственная формулировка показывает, понята ли мысль. Позже вернитесь к заметке и уточните её после следующей главы.</p>",
            "<h2>Формулы и доказательства</h2><p>Читайте формулу как предложение: что связано, при каких условиях и в каких единицах. Сопоставляйте обозначения с текстом. Один символ в разных книгах может иметь разный смысл, поэтому список обозначений — важная часть источника.</p>",
            "<p>Для проверки понимания закройте страницу и воспроизведите рассуждение по памяти. Затем сравните его с текстом. Выделяйте не весь абзац, а фразу, которая связывает понятия или формулирует ограничение модели.</p>",
            "<p>Не пропускайте подписи к рисункам и таблицам. Они часто содержат условия опыта, без которых данные легко истолковать неправильно. Сравнивайте величины только после проверки масштаба, единиц и способа измерения.</p>",
            "<p>Завершая чтение, сформулируйте три результата: что узнали, что осталось непонятным и какой пример сможете решить самостоятельно. Такой небольшой итог превращает знакомство с главой в устойчивое знание.</p>",
        ),
    )
    private fun examples(index: Int): String = when (index) {
        0 -> """<math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mi>n</mi><mo>=</mo><mfrac><mi>m</mi><mi>M</mi></mfrac></math><p>Здесь <em>n</em> — количество вещества, <em>m</em> — масса, <em>M</em> — молярная масса.</p>"""
        1 -> "<p>Примеры ионов: Na<sup>+</sup>, Ca<sup>2+</sup>, Cl<sup>−</sup>. Верхний индекс обозначает заряд.</p>"
        2 -> """<math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mn>2</mn><msub><mi>H</mi><mn>2</mn></msub><mo>+</mo><msub><mi>O</mi><mn>2</mn></msub><mo>→</mo><mn>2</mn><msub><mi>H</mi><mn>2</mn></msub><mi>O</mi></math><p>Проверьте число атомов водорода и кислорода слева и справа.</p>"""
        else -> "<ul><li>Назовите изученную модель.</li><li>Укажите её ограничения.</li><li>Приведите собственный пример.</li></ul>"
    }
}
